(() => {
  const sourceTitle = "AP Precalculus Course and Exam Description, Effective Fall 2026";
  const sourceUrl = "https://apcentral.collegeboard.org/media/pdf/ap-precalculus-course-and-exam-description.pdf";
  const unit = (number, title, entries, prompts, optional = false) => ({
    id: `apprecalc-unit-${number}`,
    name: `AP Precalculus · Unit ${number}`,
    shortName: `Unit ${number}: ${title}${optional ? " (Not on AP Exam)" : ""}`,
    builtIn: true,
    sourceTitle,
    sourceUrl,
    examStatus: optional ? "Additional course content; excluded from the AP Exam" : "Assessed on the AP Exam",
    cards: entries.map(([front, back, equation], index) => ({ id: `apprecalc-u${number}-c${index + 1}`, front, back, ...(equation ? { equation } : {}) })),
    questions: [],
    feynmanPrompts: prompts.map((prompt, index) => ({ id: `apprecalc-u${number}-f${index + 1}`, prompt })),
  });

  window.AP_PRECALCULUS_DECKS = [
    unit(1, "Polynomial and Rational Functions", [
      ["Function", "A rule that assigns exactly one output to each input in its domain."],
      ["Average rate of change", "The change in output divided by the change in input over an interval.", String.raw`\frac{f(b)-f(a)}{b-a}`],
      ["Difference quotient", "An expression for average rate of change from x to x+h.", String.raw`\frac{f(x+h)-f(x)}{h}`],
      ["Concavity", "Describes whether a graph's rate of change is increasing or decreasing over an interval."],
      ["Zeros of a function", "Input values for which the function output equals zero; graphically, x-intercepts."],
      ["Multiplicity of a zero", "The number of times its corresponding factor occurs. Odd multiplicity usually crosses the axis; even multiplicity usually touches and turns."],
      ["Polynomial end behavior", "The behavior as x approaches positive or negative infinity, determined by the leading term."],
      ["Even-degree polynomial end behavior", "Both ends point in the same direction; the leading coefficient determines whether both rise or fall."],
      ["Odd-degree polynomial end behavior", "The ends point in opposite directions; the leading coefficient determines the right-end direction."],
      ["Remainder theorem", "The remainder when f(x) is divided by x−c equals f(c)."],
      ["Factor theorem", "x−c is a factor of f(x) exactly when f(c)=0."],
      ["Polynomial long division", "Rewrites a polynomial as divisor times quotient plus a lower-degree remainder."],
      ["Rational function", "A quotient of polynomial functions whose denominator is not zero."],
      ["Vertical asymptote of a rational function", "Usually occurs at a noncanceled denominator zero where the function becomes unbounded."],
      ["Hole in a rational function", "A removable discontinuity produced by a factor canceled from numerator and denominator."],
      ["Horizontal asymptote", "A horizontal line approached as x tends to positive or negative infinity."],
      ["Slant asymptote", "A linear end-behavior asymptote found when the numerator degree is exactly one greater than the denominator degree."],
      ["Polynomial regression", "A technology-assisted polynomial model fitted to data; degree should be justified by context and residual behavior."],
      ["Residual", "Observed output minus predicted output.", "residual = observed − predicted"],
      ["Function composition", "Using one function's output as another function's input.", "(f∘g)(x)=f(g(x))"],
      ["Inverse function", "A function that reverses the input-output relationship of a one-to-one function."],
      ["Binomial theorem", "Expands a power of a binomial using binomial coefficients C(n,k).", String.raw`(a+b)^n=\sum_{k=0}^{n}C(n,k)a^{n-k}b^k`],
    ], ["How to use zeros, factors, multiplicity, and end behavior to sketch a polynomial", "How to analyze a rational function from its equation, graph, or table"]),

    unit(2, "Exponential and Logarithmic Functions", [
      ["Geometric sequence", "A sequence with a constant ratio between consecutive terms.", "a_n=a_1r^{n-1}"],
      ["Exponential function", "A function with a constant positive base raised to a variable power.", "f(x)=ab^x"],
      ["Exponential growth", "Occurs when an exponential model has a growth factor greater than 1."],
      ["Exponential decay", "Occurs when an exponential model has a growth factor between 0 and 1."],
      ["Growth factor", "The multiplier for one input-unit increase; for percent rate r, it is 1+r."],
      ["Continuous growth model", "An exponential model using base e.", "A(t)=A_0e^{kt}"],
      ["Compound interest", "Interest added periodically so later interest is earned on prior interest.", String.raw`A=P(1+\frac{r}{n})^{nt}`],
      ["Continuously compounded interest", "The limiting form of compound interest as compounding becomes continuous.", "A=Pe^{rt}"],
      ["Logarithm", "The exponent to which a base must be raised to obtain a given positive value.", String.raw`\log_b x=y ⇔ b^y=x`],
      ["Natural logarithm", "The logarithm with base e; it is the inverse of eˣ."],
      ["Product property of logarithms", "A logarithm converts multiplication into addition.", String.raw`\log_b(MN)=\log_b M+\log_b N`],
      ["Quotient property of logarithms", "A logarithm converts division into subtraction.", String.raw`\log_b(\frac{M}{N})=\log_b M-\log_b N`],
      ["Power property of logarithms", "An exponent becomes a coefficient.", String.raw`\log_b(M^p)=p\log_b M`],
      ["Change-of-base formula", "Evaluates a logarithm using another available base.", String.raw`\log_b x=\frac{\ln x}{\ln b}`],
      ["Semi-log plot", "A plot using a logarithmic scale on one axis; exponential data appear approximately linear."],
      ["Exponential regression", "A fitted model of the form abˣ used when ratios or percent changes are approximately constant."],
      ["Logistic function", "An S-shaped model with initial near-exponential growth and a limiting carrying capacity.", String.raw`f(x)=\frac{L}{1+ae^{-kx}}`],
      ["Carrying capacity", "The limiting value L approached by a logistic model."],
      ["Logistic inflection point", "The point of greatest growth rate, occurring at half the carrying capacity."],
      ["Doubling time", "The time required for an exponential quantity to double.", String.raw`T=\frac{\ln 2}{k}`],
      ["Half-life", "The time required for an exponentially decaying quantity to reach half its value.", String.raw`T=\frac{\ln 2}{|k|}`],
    ], ["How to choose among exponential, logarithmic, and logistic models", "How to solve an exponential or logarithmic equation and interpret its parameters"]),

    unit(3, "Trigonometric and Polar Functions", [
      ["Radian measure", "An angle measure equal to arc length divided by radius.", String.raw`\theta=\frac{s}{r}`],
      ["Unit circle", "The circle of radius 1 centered at the origin; coordinates at angle θ are (cos θ, sin θ)."],
      ["Sine", "For a unit-circle angle, the y-coordinate; in a right triangle, opposite over hypotenuse."],
      ["Cosine", "For a unit-circle angle, the x-coordinate; in a right triangle, adjacent over hypotenuse."],
      ["Tangent", "The ratio of sine to cosine, defined where cosine is nonzero.", String.raw`\tan\theta=\frac{\sin\theta}{\cos\theta}`],
      ["Period", "The smallest positive horizontal length after which a periodic function repeats."],
      ["Amplitude", "Half the distance between a sinusoid's maximum and minimum values; |A| in A sin(Bx+C)+D."],
      ["Sinusoidal midline", "The horizontal line halfway between maximum and minimum values; y=D in standard form."],
      ["Sinusoidal period", "For A sin(Bx+C)+D or A cos(Bx+C)+D, the period is 2π/|B|.", String.raw`period=\frac{2\pi}{|B|}`],
      ["Phase shift", "The horizontal translation of a sinusoid; in A sin(B(x−h))+D, it is h."],
      ["Secant", "The reciprocal of cosine.", String.raw`\sec\theta=\frac{1}{\cos\theta}`],
      ["Cosecant", "The reciprocal of sine.", String.raw`\csc\theta=\frac{1}{\sin\theta}`],
      ["Cotangent", "The reciprocal of tangent, equal to cosine divided by sine.", String.raw`\cot\theta=\frac{\cos\theta}{\sin\theta}`],
      ["Pythagorean identity", "The fundamental identity relating sine and cosine.", String.raw`\sin^2\theta+\cos^2\theta=1`],
      ["Angle-addition identity for sine", "Expands the sine of a sum.", String.raw`\sin(\alpha+\beta)=\sin\alpha\cos\beta+\cos\alpha\sin\beta`],
      ["Angle-addition identity for cosine", "Expands the cosine of a sum.", String.raw`\cos(\alpha+\beta)=\cos\alpha\cos\beta-\sin\alpha\sin\beta`],
      ["Inverse trigonometric function", "Returns a restricted principal angle whose trigonometric ratio equals the input."],
      ["Law of sines", "Relates side lengths to sines of opposite angles in any triangle.", String.raw`\frac{a}{\sin A}=\frac{b}{\sin B}=\frac{c}{\sin C}`],
      ["Law of cosines", "Relates three side lengths and one angle; it generalizes the Pythagorean theorem.", String.raw`c^2=a^2+b^2-2ab\cos C`],
      ["Polar coordinates", "Represent a point by directed distance r from the origin and angle θ from the positive x-axis."],
      ["Polar-to-rectangular conversion", "Convert polar coordinates using cosine and sine.", String.raw`x=r\cos\theta,\quad y=r\sin\theta`],
      ["Rectangular-to-polar conversion", "Relate rectangular coordinates to polar radius and angle.", String.raw`r^2=x^2+y^2,\quad \tan\theta=\frac{y}{x}`],
    ], ["How to build a sinusoidal model from a graph, table, or real situation", "How to move among unit-circle, graph, equation, and polar representations"]),

    unit(4, "Functions Involving Parameters, Vectors, and Matrices", [
      ["Parametric function", "Defines coordinates as functions of a shared parameter, commonly x=f(t) and y=g(t)."],
      ["Parameter", "An independent variable used to determine multiple coordinates or quantities simultaneously."],
      ["Parametric orientation", "The direction a curve is traced as the parameter increases."],
      ["Parametric line segment", "A weighted path from point P to point Q.", String.raw`r(t)=(1-t)P+tQ,\quad 0\le t\le1`],
      ["Implicit equation", "An equation relating x and y without necessarily solving one variable as a function of the other."],
      ["Parabola", "The set of points equidistant from a focus and directrix."],
      ["Ellipse", "The set of points whose distances to two foci have a constant sum.", String.raw`\frac{(x-h)^2}{a^2}+\frac{(y-k)^2}{b^2}=1`],
      ["Hyperbola", "The set of points for which the absolute difference of distances to two foci is constant.", String.raw`\frac{(x-h)^2}{a^2}-\frac{(y-k)^2}{b^2}=1`],
      ["Vector", "A quantity with magnitude and direction represented by ordered components."],
      ["Vector magnitude", "The length of a vector.", String.raw`|v|=\sqrt{v_x^2+v_y^2}`],
      ["Unit vector", "A vector of magnitude 1 used to represent direction."],
      ["Vector-valued function", "A function whose output is a vector, often representing position over time."],
      ["Matrix", "A rectangular array of values arranged in rows and columns."],
      ["Matrix product", "A matrix whose entries are row-column dot products; inner dimensions must match."],
      ["Identity matrix", "A square matrix that leaves a compatible matrix or vector unchanged under multiplication."],
      ["Determinant of a 2×2 matrix", "For a 2×2 matrix, the scalar ad−bc; a zero determinant means the matrix is not invertible.", "det(A)=ad-bc"],
      ["Inverse of a matrix", "A matrix A⁻¹ satisfying AA⁻¹=A⁻¹A=I, when it exists."],
      ["Linear transformation", "A function between vector spaces that preserves vector addition and scalar multiplication."],
      ["Transformation matrix", "A matrix whose multiplication maps an input vector to its transformed output."],
      ["Transition matrix", "A matrix of transition proportions used to model repeated movement among states."],
    ], ["How to represent and analyze motion with parametric equations and vectors", "How to multiply, invert, and use matrices for transformations and repeated-state models"], true),
  ];
})();
